import csv
import io
import re
from collections import Counter
from typing import List, Dict, Any, Union

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.lstrip("\ufeff")
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.splitlines()
    start_idx = 0
    header = None

    for i, line in enumerate(lines):
        if "," in line:
            try:
                row = next(csv.reader([line], delimiter=",", quotechar='"', escapechar=None, doublequote=True, skipinitialspace=False))
            except Exception:
                row = [c.strip() for c in line.split(",")]
            if len(row) >= 2:
                header = row
                start_idx = i + 1
                break

    if header is None:
        return {"columns": [], "rows": []}

    data_text = "\n".join(lines[start_idx:])
    if not data_text.strip():
        return {"columns": [str(x) for x in header], "rows": []}

    rows = []
    reader = csv.reader(io.StringIO(data_text), delimiter=",", quotechar='"', escapechar=None, doublequote=True, skipinitialspace=False)
    for row in reader:
        if len(row) == 0:
            continue
        rows.append([str(x) for x in row])

    width = len(header)
    normalized = []
    for row in rows:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        normalized.append(row)

    return {"columns": [str(x) for x in header], "rows": normalized}
